  "title_novice": "Каналы промоин: как читать их разрез",
  "summary": [
    {"text": "Разрез канала промоины мощностью 1–4 м — это слоистая запись размывов, глинистых прослоев и следов временных донных форм.", "claims": ["c1", "c2"]},
    {"text": "Глинистые прослои и следы донных форм отражают слабое течение, при котором канал осушается во время низкой воды.", "claims": ["c3"]},
    {"text": "Ветровые волны перерабатывают осадок у берега; в тонких разрезах зерно укрупняется вверх, что записывает миграцию береговых отмелей.", "claims": ["c4", "c5"]}
  ],
  "claims": [
    {"key": "c1", "text": "Разрезы каналов промоин имеют мощность 1–4 м и сложены фациями заполнения канала.", "kind": "observation", "unit_id": "u-035-eb990d", "page": 35, "quote": "характеризуются мощностью 1–4м и слагаются фациями заполнения канала", "numbers": ["1", "4"], "question": null},
    {"key": "c2", "text": "Фации заполнения канала содержат много поверхностей размыва, глинистых прослоев и следов временных донных форм.", "kind": "observation", "unit_id": "u-035-eb990d", "page": 35, "quote": "которые содержат многочисленные поверхности размыва, глинистые прослои и следы появления временных донных форм", "numbers": [], "question": null},
    {"key": "c3", "text": "Эти признаки отражают слабое течение, из-за которого канал осушается при низкой воде.", "kind": "inference", "unit_id": "u-035-eb990d", "page": 35, "quote": "что отражает слабое течение, приводящее к «осушению» канала во время низкой воды", "numbers": [], "question": null},
    {"key": "c4", "text": "Переработка осадка ветровыми волнами даёт маломощные волновые разрезы, где размер зерна растёт вверх.", "kind": "observation", "unit_id": "u-035-eb990d", "page": 35, "quote": "Переработка осадка ветровыми волнами приводит к формированию маломощных волновых разрезов с увеличением размера зерен кверху", "numbers": [], "question": null},
    {"key": "c5", "text": "Такой волновой разрез отражает миграцию береговых отмелей.", "kind": "inference", "unit_id": "u-035-eb990d", "page": 35, "quote": "что отражает миграцию береговых отмелей", "numbers": [], "question": null}
  ],
  "mechanism": [
    {"text": "Многочисленные поверхности размыва показывают, что поток несколько раз срезал ранее отложенный осадок.", "claims": ["c2"], "hypothesis": false},
    {"text": "Слабое течение оставляет в канале глинистые прослои и следы донных форм, потому что осадок оседает без сильного потока.", "claims": ["c2", "c3"], "hypothesis": false},
    {"text": "При низкой воде канал осушается. Поэтому в разрезе остаются следы того, что дно было открыто.", "claims": ["c3"], "hypothesis": false},
    {"text": "Ветровые волны перерабатывают осадок у берега. Зерно в таком разрезе становится крупнее вверх по разрезу.", "claims": ["c4"], "hypothesis": false},
    {"text": "Рост зерна вверх в тонком волновом разрезе записывает, как береговая отмель смещалась.", "claims": ["c5"], "hypothesis": false}
  ],
  "practice": [
    {"text": "Специалист ищет в разрезе поверхности размыва, глинистые прослои и следы донных форм. Мощность канала ищут в диапазоне 1–4 м.", "claims": ["c1", "c2"], "hypothesis": false},
    {"text": "Если при этих признаках слабое течение и осушение совпадают, разрез интерпретируют как заполнение канала.", "claims": ["c2", "c3"], "hypothesis": false},
    {"text": "Если в тонком разрезе размер зерна растёт вверх, ищут волновую переработку и береговую отмель.", "claims": ["c4", "c5"], "hypothesis": false}
  ],
  "nuances": [
    {"text": "Текст даёт диапазон мощности 1–4 м только для разрезов каналов. Вне этого диапазона правило не описано.", "claims": ["c1"], "hypothesis": false},
    {"text": "Слабое течение и осушение — интерпретация по признакам. Их не измеряют напрямую.", "claims": ["c3"], "hypothesis": false},
    {"text": "Тонкий глинистый прослой может выглядеть как самостоятельный пласт. Его отличают по связи с поверхностями размыва и по соседним слоям.", "claims": [], "hypothesis": true}
  ],
  "deeper": [
    {"title": "Почему глина в канале связана с низкой водой", "text": "Глинистые частицы оседают там, где течение слабое. Поэтому глина отмечает спокойные периоды внутри канала.", "claims": [], "hypothesis": true}
  ],
  "procedure": [],
  "numbers_conditions": [
    {"text": "Мощность разреза канала промоины: 1–4 м.", "claims": ["c1"]},
    {"text": "Условие для осушения: слабое течение и низкая вода.", "claims": ["c3"]},
    {"text": "Условие для волнового разреза: переработка ветровыми волнами, размер зерна растёт вверх.", "claims": ["c4"]}
  ],
  "terms_defined": [
    {"term": "канал промоины", "term_en": "channel", "abbr": "", "definition": "Узкий русловой канал внутри дельты. Его разрез имеет мощность 1–4 м и сложен слоями с размывами и глинистыми прослоями.", "claims": ["c1", "c2"]},
    {"term": "поверхность размыва", "term_en": "erosion surface", "abbr": "", "definition": "Граница в разрезе, где поток срезал ранее отложенные осадки. Над ней начинается новый слой.", "claims": ["c2"]},
    {"term": "временная донная форма", "term_en": "temporary bedform", "abbr": "", "definition": "Неровность дна, например рябь или дюна. Она образуется при течении и не сохраняется при его смене.", "claims": ["c2", "c3"]},
    {"term": "береговая отмель", "term_en": "shoreface shoal", "abbr": "", "definition": "Мелководный участок у берега, который переносится волнами и течением.", "claims": ["c4", "c5"]}
  ],
